+
+import com.example.model.Profile;
+import com.example.model.User;
+import ognl.OgnlException;
+import org.junit.Test;
+
+import static org.junit.Assert.*;
+
+public class ReportServiceTest {
+
+    private final ReportService reportService = new ReportService();
+
+    @Test
+    public void testLegitimateExpression() throws Exception {
+        User user = new User("Alice", "alice@example.com", new Profile("admin", true));
+        assertEquals("Alice", reportService.getReportFieldValue("name", user));
+        assertEquals("admin", reportService.getReportFieldValue("profile.role", user));
