+package com.example.service;
+
+import ognl.ClassResolver;
+
+import java.util.Map;
+
+/**
+ * A security-hardened ClassResolver that prevents loading of dangerous classes
+ * during OGNL expression evaluation.
+ */
+public class RestrictedClassResolver implements ClassResolver {
+
+    @Override
+    public Class<?> classForName(String className, Map context) throws ClassNotFoundException {
+        // Block loading of classes that could be used for code execution
+        if (className == null) {
+            throw new ClassNotFoundException("Class name cannot be null");
+        }
+
+        String normalizedName = className.trim();
+
+        // Block reflection and dangerous classes
+        if (normalizedName.startsWith("java.lang.reflect.")
+                || normalizedName.equals("java.lang.Runtime")
+                || normalizedName.equals("java.lang.ProcessBuilder")
+                || normalizedName.equals("java.lang.ClassLoader")
+                || normalizedName.equals("java.lang.Thread")
+                || normalizedName.equals("java.lang.ThreadGroup")
+                || normalizedName.equals("java.lang.System")
+                || normalizedName.equals("ognl.OgnlRuntime")
+                || normalizedName.startsWith("java.io.")) {
+            throw new ClassNotFoundException("Access to class '" + normalizedName + "' is not permitted");
+        }
+
+        return Class.forName(normalizedName);
+    }
+}
