+package com.example.service;
+
+import ognl.AbstractMemberAccess;
+
+import java.lang.reflect.Member;
+import java.lang.reflect.Method;
+import java.lang.reflect.Modifier;
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Set;
+
+/**
+ * A security-hardened MemberAccess implementation that restricts OGNL expression evaluation
+ * to prevent code execution and other injection attacks.
+ */
+public class SecureMemberAccess extends AbstractMemberAccess {
+
+    private static final Set<String> DENIED_CLASSES = new HashSet<>(Arrays.asList(
+        "java.lang.Runtime",
+        "java.lang.ProcessBuilder",
+        "java.lang.ClassLoader",
+        "java.lang.Thread",
+        "java.lang.ThreadGroup",
+        "java.lang.System",
+        "java.lang.reflect.Method",
+        "java.lang.reflect.Field",
+        "java.lang.reflect.Constructor",
+        "java.io.File",
+        "java.net.URLClassLoader",
+        "java.net.Socket",
+        "java.net.ServerSocket",
+        "ognl.OgnlRuntime"
+    ));
+
+    private static final Set<String> DENIED_METHODS = new HashSet<>(Arrays.asList(
+        "getClass",
+        "forName",
+        "getMethod",
+        "getDeclaredMethod",
+        "getField",
+        "getDeclaredField",
+        "getConstructor",
+        "getDeclaredConstructor",
+        "newInstance",
+        "exec",
+        "invoke",
+        "loadClass",
+        "defineClass",
+        "wait",
+        "notify",
+        "notifyAll"
+    ));
+
+    @Override
+    public boolean isAccessible(java.util.Map context, Object target, Member member, String propertyName) {
+        if (member == null) {
+            return false;
+        }
+
+        // Only allow public members
+        if (!Modifier.isPublic(member.getModifiers())) {
+            return false;
+        }
+
+        // Block access to denied classes
+        Class<?> declaringClass = member.getDeclaringClass();
+        if (declaringClass != null) {
+            String className = declaringClass.getName();
+            if (DENIED_CLASSES.contains(className)) {
+                return false;
+            }
+
+            // Block access to Class methods that enable reflection attacks
+            if (Class.class.equals(declaringClass)) {
+                return false;
+            }
+        }
+
+        // For methods, only allow getter-style methods and block dangerous methods
+        if (member instanceof Method) {
+            Method method = (Method) member;
+            String methodName = method.getName();
+
+            // Block explicitly denied methods
+            if (DENIED_METHODS.contains(methodName)) {
+                return false;
+            }
+
+            // Only allow getter-style methods: get*, is*, set* is not needed for report generation
+            // but we'll allow it for completeness since some data models may use setters
+            boolean isGetter = methodName.startsWith("get") || methodName.startsWith("is");
+            boolean isSetter = methodName.startsWith("set") && method.getParameterCount() == 1;
+
+            if (!isGetter && !isSetter) {
+                return false;
+            }
+        }
+
+        return true;
+    }
+}
